import sys

def solve(s):
    n = len(s)
    # RBS must have even length
    if n % 2 != 0:
        return "NO"

    fixed_open = s.count('(')
    num_q = s.count('?')
    # We need n/2 opening brackets total
    open_needed = n // 2 - fixed_open

    # Sanity check: open_needed must be in [0, num_q]
    if open_needed < 0 or open_needed > num_q:
        return "NO"

    balance = 0
    used_open = 0  # number of '(' assigned to '?' so far
    remaining_q = num_q  # number of '?' remaining (including current)

    for c in s:
        if c == '(':
            balance += 1
        elif c == ')':
            balance -= 1
        elif c == '?':
            # Check if this '?' is forced
            forced_open = False
            forced_close = False

            if balance == 0:
                # Must put '(' to avoid negative balance
                forced_open = True
            elif used_open == open_needed:
                # No more '(' quota, must put ')'
                forced_close = True
            elif (open_needed - used_open) == remaining_q:
                # Must use all remaining '?' (including current) as '('
                forced_open = True

            if forced_open:
                balance += 1
                used_open += 1
            elif forced_close:
                balance -= 1
            else:
                # Free choice exists → multiple valid assignments
                return "NO"

            remaining_q -= 1
        # else: ignore (shouldn't happen with valid input)

    # Final balance should be 0 for a valid RBS
    if balance != 0:
        return "NO"

    return "YES"

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    t = int(input_data[0])
    results = []

    for i in range(1, t + 1):
        s = input_data[i]
        results.append(solve(s))

    print('\n'.join(results))

if __name__ == "__main__":
    main()
